INSERT INTO `item_template_locale` (`ID`, `locale`, `Name`, `Description`, `VerifiedBuild`) VALUES
(84035, 'frFR', 'Yu Wu, bâton des Brumes', 'Les brumes du Serpent de jade s’amassent autour de sa tête, dans l’attente d’une blessure à refermer.', 0),
(84035, 'deDE', 'Yu Wu, Stab der Nebel', 'Die Nebel der Jadeschlange sammeln sich um seinen Kopf und warten auf eine Wunde, die sie schließen können.', 0),
(84035, 'esES', 'Yu Wu, bastón de las Brumas', 'Las brumas del Dragón de Jade se acumulan en torno a su cabeza, a la espera de una herida que cerrar.', 0),
(84035, 'ruRU', 'Юй У, посох Туманов', 'Туманы Нефритовой Змеи клубятся вокруг его навершия в ожидании раны, которую нужно затянуть.', 0),
(84036, 'frFR', 'Jin Gu, bâton du Roi-Singe', 'Son bois sent encore le breuvage que le Roi-Singe y a renversé en riant.', 0),
(84036, 'deDE', 'Jin Gu, Stab des Affenkönigs', 'Sein Holz riecht noch nach dem Gebräu, das der Affenkönig lachend darüber verschüttet hat.', 0),
(84036, 'esES', 'Jin Gu, bastón del Rey Mono', 'Su madera aún huele al brebaje que el Rey Mono derramó sobre ella entre risas.', 0),
(84036, 'ruRU', 'Цзинь Гу, посох Короля обезьян', 'Его древко до сих пор пахнет хмелем, который со смехом пролил на него Король обезьян.', 0),
(84037, 'frFR', 'Tian Lei, Poing de la Foudre céleste', 'Le poing droit des Cieux. Le tonnerre y gronde avant chaque coup.', 0),
(84037, 'deDE', 'Tian Lei, Faust des Himmelsblitzes', 'Die rechte Faust der Himmel. Vor jedem Schlag grollt darin der Donner.', 0),
(84037, 'esES', 'Tian Lei, Puño del Rayo celestial', 'El puño derecho de los Cielos. El trueno retumba en él antes de cada golpe.', 0),
(84037, 'ruRU', 'Тянь Лэй, Кулак Небесной молнии', 'Правый кулак Небес. Перед каждым ударом в нем рокочет гром.', 0),
(84038, 'frFR', 'Tian Feng, Poing du Vent céleste', 'Le poing gauche des Cieux. Le vent le suit partout où il frappe.', 0),
(84038, 'deDE', 'Tian Feng, Faust des Himmelswindes', 'Die linke Faust der Himmel. Der Wind folgt ihr, wohin sie auch schlägt.', 0),
(84038, 'esES', 'Tian Feng, Puño del Viento celestial', 'El puño izquierdo de los Cielos. El viento lo sigue allá donde golpea.', 0),
(84038, 'ruRU', 'Тянь Фэн, Кулак Небесного ветра', 'Левый кулак Небес. Ветер следует за ним, куда бы он ни ударил.', 0),
(84135, 'frFR', 'Rouleau trempé de brume', 'L’encre coule dès qu’on le déroule.', 0),
(84135, 'deDE', 'Nebelgetränkte Schriftrolle', 'Die Tinte verläuft, sobald Ihr sie aufrollt.', 0),
(84135, 'esES', 'Pergamino empapado de bruma', 'La tinta se corre en cuanto lo desenrollas.', 0),
(84135, 'ruRU', 'Пропитанный туманом свиток', 'Чернила расплываются, стоит его развернуть.', 0),
(84136, 'frFR', 'Livre de recettes taché de bière', 'Chaque page sent le riz fermenté.', 0),
(84136, 'deDE', 'Biergetränktes Rezeptbuch', 'Jede Seite riecht nach vergorenem Reis.', 0),
(84136, 'esES', 'Recetario manchado de cerveza', 'Cada página huele a arroz fermentado.', 0),
(84136, 'ruRU', 'Залитая пивом книга рецептов', 'Каждая страница пахнет перебродившим рисом.', 0),
(84137, 'frFR', 'Cerf-volant déchiré par l’orage', 'Une image est peinte sur ce qui reste de son papier.', 0),
(84137, 'deDE', 'Vom Sturm zerrissener Drachen', 'Auf dem, was von seinem Papier übrig ist, ist ein Bild gemalt.', 0),
(84137, 'esES', 'Cometa rasgada por la tormenta', 'Hay una imagen pintada en lo que queda de su papel.', 0),
(84137, 'ruRU', 'Разорванный бурей воздушный змей', 'На уцелевшей бумаге нарисована картинка.', 0),
(84138, 'frFR', 'Bannière effilochée par le vent', 'Une image est encore tissée dans l’étoffe.', 0),
(84138, 'deDE', 'Vom Wind zerfranstes Banner', 'In den Stoff ist noch ein Bild gewebt.', 0),
(84138, 'esES', 'Estandarte deshilachado por el viento', 'Aún hay una imagen tejida en la tela.', 0),
(84138, 'ruRU', 'Истрепанное ветром знамя', 'В ткань все еще вплетена картинка.', 0);
